    Item {
        name = name.trim().toUpperCase();
        count = Math.max(0, count);
    }
    String summary() { return label() + ":" + count; }
}
public class Main {
    public static void main(String[] args) {
        var x = new Item(" item0 ", -2);
        System.out.print(x.summary());
    }
}

